import { defineService, implementService } from '@wix/services-definitions';
import { SignalsServiceDefinition, } from '@wix/services-definitions/core-services/signals';
import { items } from '@wix/data';
import { fetchFieldOptions as fetchFieldOptionsUtil, loadCollectionSchema, createReferencedCollectionItem as createReferencedCollectionItemUtil, } from './cms-utils.js';
/**
 * Service definition for the CMS Item service.
 */
export const CmsItemServiceDefinition = defineService('CmsItem');
/**
 * Shared function to load a single item from Wix Data
 */
const loadItem = async (collectionId, itemId, singleRefFieldIds = [], multiRefFieldIds = []) => {
    if (!collectionId) {
        throw new Error('No collection ID provided');
    }
    if (!itemId) {
        throw new Error('No item ID provided');
    }
    // Use query instead of get to support include() for reference fields
    let query = items.query(collectionId).eq('_id', itemId);
    // Include reference fields if specified
    const allRefFieldIds = [...singleRefFieldIds, ...multiRefFieldIds];
    if (allRefFieldIds.length > 0) {
        query = query.include(...allRefFieldIds);
    }
    const result = await query.find();
    if (!result.items || result.items.length === 0) {
        throw new Error('Item not found');
    }
    const item = result.items[0];
    if (!item) {
        throw new Error('Item not found');
    }
    return item;
};
/**
 * Implementation of the CMS Item service that manages reactive item data.
 */
export const CmsItemServiceImplementation = implementService.withConfig()(CmsItemServiceDefinition, ({ getService, config }) => {
    const signalsService = getService(SignalsServiceDefinition);
    // Initialize with pre-loaded item if provided, otherwise with empty object
    const itemSignal = signalsService.signal(config.item || { _id: '' });
    const loadingSignal = signalsService.signal(false);
    const fetchingSignal = signalsService.signal(false);
    const errorSignal = signalsService.signal(null);
    const collectionSchemaSignal = signalsService.signal(null);
    const loadItemData = async () => {
        const hasNoItem = !itemSignal.get()?._id || itemSignal.get()?._id === '';
        if (hasNoItem) {
            loadingSignal.set(true);
        }
        fetchingSignal.set(true);
        errorSignal.set(null);
        try {
            const item = await loadItem(config.collectionId, config.itemId, config.singleRefFieldIds, config.multiRefFieldIds);
            itemSignal.set(item);
        }
        catch (err) {
            const errorMessage = err instanceof Error ? err.message : 'Failed to load item';
            errorSignal.set(errorMessage);
            console.error(`Failed to load item "${config.itemId}" from collection "${config.collectionId}":`, err);
        }
        finally {
            if (hasNoItem) {
                loadingSignal.set(false);
            }
            fetchingSignal.set(false);
        }
    };
    const updateItem = async (itemData) => {
        try {
            const updatedItem = await items.update(config.collectionId, {
                ...itemData,
                _id: config.itemId,
            });
            // Reload item to maintain consistency with backend data
            await loadItemData();
            return updatedItem;
        }
        catch (err) {
            console.error(`Failed to update item "${config.itemId}" in collection "${config.collectionId}":`, err);
            throw err; // Re-throw for component error handling
        }
    };
    const deleteItem = async () => {
        try {
            await items.remove(config.collectionId, config.itemId);
            // No reload after delete since item no longer exists
        }
        catch (err) {
            console.error(`Failed to delete item "${config.itemId}" from collection "${config.collectionId}":`, err);
            throw err; // Re-throw for component error handling
        }
    };
    const linkItem = async (params) => {
        try {
            await items.insertReference(config.collectionId, params.referenceFieldId, config.itemId, params.referencedItemIds);
            // Reload item to maintain consistency with backend data
            await loadItemData();
        }
        catch (err) {
            console.error(`Failed to link item "${config.itemId}" in collection "${config.collectionId}":`, err);
            throw err; // Re-throw for component error handling
        }
    };
    const unlinkItem = async (params) => {
        try {
            await items.removeReference(config.collectionId, params.referenceFieldId, params.itemId, params.referencedItemIds);
            // Reload item to maintain consistency with backend data
            await loadItemData();
        }
        catch (err) {
            console.error(`Failed to unlink item "${config.itemId}" from collection "${config.collectionId}":`, err);
            throw err; // Re-throw for component error handling
        }
    };
    const fetchFieldOptions = async (fieldId) => {
        const getSchema = async () => {
            let schema = collectionSchemaSignal.get();
            if (!schema) {
                schema = await loadCollectionSchema(config.collectionId);
                if (schema) {
                    collectionSchemaSignal.set(schema);
                }
            }
            return schema;
        };
        return await fetchFieldOptionsUtil({
            collectionId: config.collectionId,
            fieldId,
            getSchema,
        });
    };
    const createReferencedCollectionItem = async (referenceFieldId, itemData) => {
        try {
            const getSchema = async () => {
                let schema = collectionSchemaSignal.get();
                if (!schema) {
                    schema = await loadCollectionSchema(config.collectionId);
                    if (schema) {
                        collectionSchemaSignal.set(schema);
                    }
                }
                return schema;
            };
            const createdItem = await createReferencedCollectionItemUtil({
                referenceFieldId,
                itemData,
                getSchema,
            });
            return createdItem;
        }
        catch (err) {
            console.error(`Failed to create item in referenced collection for field "${referenceFieldId}" in collection "${config.collectionId}":`, err);
            throw err; // Re-throw for component error handling
        }
    };
    // Auto-load item on service initialization only if not pre-loaded
    if (!config.item) {
        loadItemData();
    }
    return {
        loadItem: loadItemData,
        itemSignal,
        loadingSignal,
        fetchingSignal,
        errorSignal,
        collectionId: config.collectionId,
        updateItem,
        deleteItem,
        linkItem,
        unlinkItem,
        fetchFieldOptions,
        createReferencedCollectionItem,
    };
});
/**
 * Loads initial data for the CMS Item service.
 */
export const loadCmsItemServiceInitialData = async (collectionId, itemId, singleRefFieldIds, multiRefFieldIds) => {
    try {
        if (!collectionId) {
            throw new Error('No collection ID provided');
        }
        if (!itemId) {
            throw new Error('No item ID provided');
        }
        // Load item on the server using shared function
        const item = await loadItem(collectionId, itemId, singleRefFieldIds, multiRefFieldIds);
        return {
            [CmsItemServiceDefinition]: {
                collectionId,
                itemId,
                item,
                singleRefFieldIds,
                multiRefFieldIds,
            },
        };
    }
    catch (error) {
        console.error(`Failed to load item config for "${itemId}" from collection "${collectionId}":`, error);
        throw error; // Re-throw to let caller handle 404 logic
    }
};
/**
 * Service binding helper that bundles everything together for the service manager.
 */
export const cmsItemServiceBinding = (servicesConfigs) => {
    return [
        CmsItemServiceDefinition,
        CmsItemServiceImplementation,
        servicesConfigs[CmsItemServiceDefinition],
    ];
};
